import React from "react";

function RatingStars({ value = 0, onChange = () => {}, max = 5 }) {

  const stars = Array.from({ length: max }, (_, i) => i + 1);
  return (
    <div className="stars"  aria-label="rating">
      {stars.map((n) => (
        <button
          key={n}
          type="button"
          role="radio"
          aria-checked={n === value}
          onClick={() => onChange(n)}
          style={{
            fontSize: "1.4rem",
            background: "transparent",
            border: "none",
            cursor: "pointer",
            padding: "2px 4px"
          }}
        >
          {n <= value ? "★" : "☆"}
        </button>
      ))}
      <span style={{ marginLeft: 8 }}>{value}/{max}</span>
    </div>
  );
}

export default RatingStars;
